 auto valid=validate_private_shop_daily_rent_layout(c,&s);if(!valid.ok)return {false,{},valid.error};if(limit<0||limit>c.tick())return fail<std::map<StableId,PrivateShopRentLedgerView>>("PrivateShopRentPhaseMismatch");
 if(catalog.version!=1||catalog.profile!="opening_anchored_two_halfdays_v1"||catalog.arrears_policy!="one_unpaid_period_then_suspend_v1"||s.last_step_tick!=limit)return fail<std::map<StableId,PrivateShopRentLedgerView>>("PrivateShopDailyRentClockMismatch");
