   if(!n||!pn||*pn!=*n+1||!paid||paid->id!=p->local_payment_id||!header(c,paid->id,"local_payment","obligation_payment","local_economy")||!adjacent(c,p->id,paid->id)||!due||paid->arrear_id!=due->id||paid->obligation_id!=shop->rent_obligation_id||paid->from_wallet_id!=shop->wallet_id||paid->to_wallet_id!=shop->terms.lessor_wallet_id||paid->authority_ref!=shop->id||paid->amount!=due->original_due||due->paid_amount!=paid->amount||paid->due_tick!=due->due_tick||paid->tick!=p->tick||p->tick<r.last_tick||p->tick>limit||v.closed||v.pending_arrear_id!=due->id||!settled.insert(a->id).second||!local_payments.insert(paid->id).second||!seen_payments.insert(p->id).second)return fail<std::map<StableId,PrivateShopRentLedgerView>>("PrivateShopRentOriginalPaymentMismatch",p->id);
   const bool automatic=p->funding_kind=="automatic_shop",shop_cash=automatic||p->funding_kind=="proprietor_shop";const bool proprietor=p->funding_kind=="proprietor_personal",executor=p->funding_kind=="executor_personal";const auto* actor=c.actor(p->actor_id);const auto* wallet=c.wallet(p->payer_wallet_id);
   if(automatic){if(a->automatic_payment_fact_id!=p->id||p->tick!=a->tick||!p->actor_id.empty()||p->payer_wallet_id!=shop->wallet_id||!p->mandate_fact_id.empty()||!p->death_notice_binding_fact_id.empty())return fail<std::map<StableId,PrivateShopRentLedgerView>>("PrivateShopRentAutomaticPaymentMismatch",p->id);}
