Status validate_private_shop_daily_rent_sources(const CommonStore& c,const LocalEconomyState& e,const PrivateShopState& shops,const PrivateShopDailyRentCatalog& catalog,const PrivateShopDailyRentState& state,const DynamicStepInput* phase){if(phase&&(c.tick()==INT64_MAX||phase->from_tick!=c.tick()||phase->to_tick!=c.tick()+1))return {false,{},common_failure("PrivateShopRentPhaseMismatch").error};auto result=replay(c,e,shops,catalog,state,c.tick());return result.ok?common_success():Status{false,{},result.error};}
Outcome<PrivateShopRentLedgerView> read_private_shop_rent_ledger(const CommonStore& c,const LocalEconomyState& e,const PrivateShopState& shops,const PrivateShopDailyRentCatalog& catalog,const PrivateShopDailyRentState& state,const StableId& shop,const DynamicStepInput* phase){if(phase&&(c.tick()==INT64_MAX||phase->from_tick!=c.tick()||phase->to_tick!=c.tick()+1))return {false,{},common_failure("PrivateShopRentPhaseMismatch").error};auto result=replay(c,e,shops,catalog,state,c.tick());if(!result.ok)return {false,{},result.error};auto found=result.value.find(shop);return found==result.value.end()?fail<PrivateShopRentLedgerView>("UnknownPrivateShop",shop):Outcome<PrivateShopRentLedgerView>{true,found->second,{}};}
Outcome<std::vector<PrivateShopRentLedgerView>> read_private_shop_rent_before_calendar(const CommonStore& c,const LocalEconomyState& e,const PrivateShopState& shops,const PrivateShopDailyRentCatalog& catalog,const PrivateShopDailyRentState& state,const DynamicStepInput& step){if(step.from_tick<0||step.from_tick==INT64_MAX||step.to_tick!=step.from_tick+1||c.tick()!=step.to_tick||state.last_step_tick!=step.from_tick)return fail<std::vector<PrivateShopRentLedgerView>>("PrivateShopRentCalendarPhaseMismatch");auto original=replay(c,e,shops,catalog,state,step.from_tick);if(!original.ok)return {false,{},original.error};std::vector<PrivateShopRentLedgerView> out;for(const auto& row:original.value)out.push_back(row.second);return {true,std::move(out),{}};}

